// file: components/data/data/entities/reader.nuc
@entity("readers")
Reader()
  @primary(generated = true)
  id: int
  name: string
  @column(unique = true)
  email: string

// file: components/domain/domain/models/new_reader.nuc
model NewReader
  @minLength(2) name: string
  @email email: string

// file: components/domain/domain/usecases/create_reader.nuc
usecase CreateReader(readers: ReadersAppComponent)
  exec(input: NewReader) Result<Error, Reader>
    taken = ~readers.where({ "email": input.email }).exists()
    if taken
      return Err(Conflict("email already exists"))
    saved = ~readers.save(Reader(name = input.name, email = input.email))
    Ok(saved)

// file: components/data/data/repositories/reader_repository.nuc
repository ReaderRepository
  byEmail(email: string) Result<Error, Reader>
    where({ "email": email })
    getOne()

  save(reader: Reader) Reader
    ~add(reader)

  remove(id: int) Reader
    ~remove(id)

usecase CreateReader(readers: ReaderRepository)
  exec(input: NewReader) Result<Error, Reader>
    taken = ~readers.byEmail(input.email)
    if taken
      return Err(Conflict("email already exists"))
    saved = ~readers.save(Reader(name = input.name, email = input.email))
    Ok(saved)

// file: components/components/components_appcomponent.nuc
appcomponent ComponentsAppComponent
  create() = CreateReader.exec

// file: components/api/api/readers_controller.nuc
@controller("readers")
controller ReadersController(readers: ReadersAppComponent)
  @post()
  create(input: NewReader) Result<Error, Reader>
